/* 宝可梦大赛报名处 — single-scene, client-only Phaser 3 game.
 * Map: assets/arena.json (generated by build_map.py). Tiles + player sprite from
 * ariroffe/personal-website (MIT code; art credits in README).
 * Movement is tile-by-tile like the GBA games; no server state. */
(function () {
  'use strict';

  const TILE = 32;
  const STEP_MS = 180;          // time to walk one tile
  const DIRS = {
    left:  { dx: -1, dy: 0, anim: 'left' },
    right: { dx: 1,  dy: 0, anim: 'right' },
    up:    { dx: 0,  dy: -1, anim: 'back' },
    down:  { dx: 0,  dy: 1,  anim: 'front' },
  };

  const TEXT = {
    zh: {
      npc: ['欢迎来到宝可梦竞技场！', '每只宝可梦都是这里的擂主，要挑战哪一只？'],
      ask: '要挑战哪只擂主？',
      askTier: '要挑战哪一档的擂主？',
      tier: (n, name, count) => `第 ${n} 档 · ${name}（${count}）`,
      askPage: (p, n) => `要挑战哪只擂主？（第 ${p}/${n} 页）`,
      prevPage: '◀ 上一页',
      nextPage: '下一页 ▶',
      back: '返回',
      cancel: '下次再说',
      bye: ['好的，随时欢迎再来！'],
      go: m => [`好的！挑战擂主${m}！`, '你的挑战者已经安排好了，对战马上开始！'],
      win: ['恭喜你击败了擂主！真是精彩的对战！', '想再挑战的话随时找我哦。'],
      lose: ['擂主守住了……不过你的挑战者表现得很棒！', '要不要再挑战一次？'],
      hint: '方向键 / WASD 移动，空格 / 回车 对话',
      hintTouch: '方向键移动，走到柜台前按 A 对话',
      hintMenu: '↑ / ↓ 选择，空格 / 回车 确认',
      hintBattle: '自动对战中，空格 / 回车 / 点击 可加快',
      next: '▼',
      // main-hall receptionist: entry fee
      feeNpc: ['欢迎来到宝可梦竞技场！'],
      feeAsk: '你要挑战哪一档？',
      feeTier: (n, name, fee) => `第 ${n} 档 · ${name}（${fee}U）`,
      payText: (n, name, fee) => `第 ${n} 档 · ${name}，报名费 ${fee} USDC\n请使用 Arbitrum 网络转账`,
      payNote: '仅收 Arbitrum One 网络上的 USDC，其他网络或币种转入无法找回。',
      payAlt: 'Arbitrum 收款地址二维码',
      copy: '复制地址',
      copied: '地址已复制',
      copyFail: '复制失败，请长按地址手动复制',
      close: '关闭',
      boardTitle: '公告栏',
      boardBody: ['欢迎来到竞技场！（点击观赛）'],
      boardAlt: '公告栏',
      betsTitle: '最近比赛',
      betsCols: ['训练师', '参赛费', '档位', '结果'],
      betsLoading: '比赛载入中…',
      betsEmpty: '还没有比赛',
      betsError: '比赛载入失败，请稍后再试',
      betsTier: (n, name) => `第${'一二三四五六七八九十'[n - 1]}档（${name}）`,
      betsWin: m => (m > 1 ? `胜（暴击${m}倍）` : '胜'),
      betsLoss: '负',
      betsPending: '待开奖',
      betsPage: (p, n) => `第 ${p}/${n} 页`,
      betsPrev: '◀ 上一页',
      betsNext: '下一页 ▶',
      betsCaption: '最近比赛，每页 10 笔，数据直接读取 Arbitrum 链上记录',
      betsWatch: (a, fee, res) => `观看 ${a} 的比赛：${fee}，${res}`,
      betsReplayFail: '比赛回放载入失败，请稍后再试',
    },
    en: {
      npc: ['Welcome to the Pokémon Arena!', 'Every Pokémon here is a champion. Which one will you challenge?'],
      ask: 'Which champion will you challenge?',
      askTier: 'Which tier of champions will you challenge?',
      tier: (n, name, count) => `Tier ${n} · ${name} (${count})`,
      askPage: (p, n) => `Which champion will you challenge? (page ${p}/${n})`,
      prevPage: '◀ Prev',
      nextPage: 'Next ▶',
      back: 'Back',
      cancel: 'Maybe later',
      bye: ['All right. Come back any time!'],
      go: m => [`Great! You will challenge ${m}!`, 'Your challenger is ready. The battle starts now!'],
      win: ['You beat the champion! What a great battle!', 'Come see me if you want another round.'],
      lose: ['The champion held on... but your challenger did really well!', 'Why not challenge again?'],
      hintMenu: '↑ / ↓ to choose, Space / Enter to confirm',
      hintBattle: 'Auto battle. Space / Enter / tap to speed up',
      feeNpc: ['Welcome to the Pokémon Arena!'],
      feeAsk: 'Which tier will you challenge?',
      feeTier: (n, name, fee) => `Tier ${n} · ${name} (${fee}U)`,
      payText: (n, name, fee) => `Tier ${n} · ${name}: entry fee ${fee} USDC\nPlease send on the Arbitrum network`,
      payNote: 'USDC on Arbitrum One only. Funds sent on other networks or in other coins cannot be recovered.',
      payAlt: 'QR code of the Arbitrum payment address',
      copy: 'Copy address',
      copied: 'Address copied',
      copyFail: 'Copy failed. Press and hold the address to copy it.',
      close: 'Close',
      boardTitle: 'Notice Board',
      boardBody: ['Welcome to the Arena! (Tap a match to watch)'],
      boardAlt: 'Notice board',
      betsTitle: 'Recent matches',
      betsCols: ['Trainer', 'Entry fee', 'Tier', 'Result'],
      betsLoading: 'Loading matches…',
      betsEmpty: 'No matches yet',
      betsError: 'Could not load matches. Please try again later.',
      betsTier: (n, name) => `Tier ${n} (${name})`,
      betsWin: m => (m > 1 ? `Win (Crit ×${m})` : 'Win'),
      betsLoss: 'Loss',
      betsPending: 'Pending',
      betsPage: (p, n) => `Page ${p}/${n}`,
      betsPrev: '◀ Prev',
      betsNext: 'Next ▶',
      betsCaption: 'Recent matches, 10 per page, read directly from Arbitrum',
      betsWatch: (a, fee, res) => `Watch the match of ${a}: ${fee}, ${res}`,
      betsReplayFail: 'Could not load the replay. Please try again later.',
      hint: 'Arrows / WASD to move, Space / Enter to talk',
      hintTouch: 'D-pad to move, press A at the counter to talk',
      next: '▼',
    },
  };
  const lang = () => (window.I18n && window.I18n.lang === 'en' ? 'en' : 'zh');

  // ---------- dialog box (DOM, so CJK text renders crisply and is screen-reader friendly) ----------
  // Modes: start(lines, onDone) = player pages through; say(text, hold) = auto-play line (battle);
  // choose(prompt, options, onPick) = pick one option (keyboard ↑/↓ + Space, or tap).
  const dialog = {
    el: null, textEl: null, menuEl: null, lines: [], idx: 0, typing: null, open: false,
    busy: false, onDone: null, sayDone: null, sayTimer: null, choice: null,
    init() {
      this.el = document.getElementById('dialog');
      this.textEl = document.getElementById('dialog-text');
      this.menuEl = document.getElementById('dialog-menu');
      this.el.addEventListener('click', () => this.advance());
      document.addEventListener('keydown', e => {
        if (!this.choice) return;
        const k = e.key;
        if (k === 'ArrowUp' || k === 'w' || k === 'W') { this.move(-1); e.preventDefault(); }
        else if (k === 'ArrowDown' || k === 's' || k === 'S') { this.move(1); e.preventDefault(); }
      });
    },
    type(full, after) {
      let n = 0;
      clearInterval(this.typing);
      this.textEl.textContent = '';
      this.el.setAttribute('aria-label', full);
      this.typingDone = after || null;
      this.typing = setInterval(() => {
        n++;
        this.textEl.textContent = full.slice(0, n);
        if (n >= full.length) this.endTyping();
      }, 30);
      this.full = full;
    },
    endTyping() {
      clearInterval(this.typing); this.typing = null;
      this.textEl.textContent = this.full;
      const f = this.typingDone; this.typingDone = null;
      if (f) f();
    },
    showBox(next) { this.open = true; this.el.hidden = false; this.el.classList.toggle('no-next', !next); },
    start(lines, onDone) {
      this.clearMenu();
      this.lines = lines; this.idx = 0; this.onDone = onDone || null;
      this.showBox(true);
      this.type(this.lines[0]);
    },
    hold(text) { this.clearMenu(); this.showBox(false); this.full = text; this.textEl.textContent = text; },
    say(text, hold = 900) {
      this.clearMenu();
      this.showBox(false);
      return new Promise(resolve => {
        this.sayDone = () => { clearTimeout(this.sayTimer); this.sayDone = null; resolve(); };
        this.type(text, () => { this.sayTimer = setTimeout(() => this.sayDone && this.sayDone(), hold); });
      });
    },
    // extra: optional DOM node shown between the prompt and the menu (e.g. the payment QR)
    choose(prompt, options, onPick, sel = 0, extra = null) {
      this.lines = []; this.onDone = null;
      this.showBox(false);
      this.type(prompt);
      this.setExtra(extra);
      this.menuEl.innerHTML = '';
      this.choice = { options, onPick, sel: Math.max(0, Math.min(sel, options.length - 1)), btns: [] };
      options.forEach((o, i) => {
        const b = document.createElement('button');
        b.type = 'button'; b.textContent = o.label; b.setAttribute('role', 'menuitem');
        b.addEventListener('click', e => { e.stopPropagation(); this.choice.sel = i; this.confirm(); });
        this.menuEl.appendChild(b);
        this.choice.btns.push(b);
      });
      this.menuEl.hidden = false;
      this.move(0);
    },
    move(d) {
      const c = this.choice, n = c.options.length;
      if (d && window.ArenaMusic) window.ArenaMusic.sfx('select');
      c.sel = (c.sel + d + n) % n;
      c.btns.forEach((b, i) => { const on = i === c.sel; b.classList.toggle('sel', on); b.setAttribute('aria-current', on ? 'true' : 'false'); });
      c.btns[c.sel].focus({ preventScroll: true });
    },
    confirm() {
      const c = this.choice; if (!c) return;
      const pick = c.options[c.sel].value;
      // Poké Ball sound only when a Pokémon is sent out; menus/back just beep
      const isMon = typeof pick === 'string' && !pick.startsWith('__');
      if (window.ArenaMusic) window.ArenaMusic.sfx(isMon ? 'ball' : 'select');
      this.clearMenu(); this.close();
      c.onPick(pick);
    },
    setExtra(node) {
      if (this.extraEl) this.extraEl.remove();
      this.extraEl = node || null;
      if (node) this.el.insertBefore(node, this.menuEl);
      this.el.classList.toggle('has-extra', !!node);
    },
    // Full notice (e.g. the lobby board): node replaces the text line; any press closes it.
    notice(node) {
      this.clearMenu();
      this.lines = ['']; this.idx = 0; this.onDone = null;
      clearInterval(this.typing); this.typing = null;
      this.full = ''; this.textEl.textContent = '';
      this.el.setAttribute('aria-label', node.textContent);
      this.showBox(true);
      this.el.classList.add('is-notice');
      this.setExtra(node);
    },
    clearMenu() { this.choice = null; this.noticeHook = null; this.setExtra(null); if (this.menuEl) { this.menuEl.hidden = true; this.menuEl.innerHTML = ''; } },
    advance() {
      if (!this.open) return;
      if (this.noticeHook && this.noticeHook()) return;   // notice board: Space/A plays the selected match
      if (this.typing) { this.endTyping(); return; }   // first press finishes the line
      if (this.choice) { this.confirm(); return; }
      if (this.sayDone) { this.sayDone(); return; }   // skip the pause in auto-play
      if (this.busy) return;
      this.idx++;
      if (this.idx >= this.lines.length) {
        const f = this.onDone; this.close(); if (f) f();
      } else this.type(this.lines[this.idx]);
    },
    close() {
      this.open = false; this.el.hidden = true;
      this.el.classList.remove('is-notice'); this.setExtra(null); this.noticeHook = null;
      clearInterval(this.typing); this.typing = null;
    },
  };

  const PAGE_SIZE = 10;   // Pokémon per menu page

  // Entry fee (main-hall receptionist): tier n costs n USDC on Arbitrum One.
  // The QR (assets/pay/arb-usdc-qr.png, made by pay-gen/build_pay_qr.py) encodes PAY_ADDRESS only.
  const PAY_ADDRESS = '0xf589fe018faF04b663eEA702E59E8601c65e5354';
  const PAY_QR = 'assets/pay/arb-usdc-qr.png?v=20261101e';
  const tierFee = n => n;

  async function copyText(s) {
    try { await navigator.clipboard.writeText(s); return true; } catch (e) { /* fall back below */ }
    const ta = document.createElement('textarea');
    ta.value = s; ta.setAttribute('readonly', ''); ta.style.position = 'fixed'; ta.style.opacity = '0';
    document.body.appendChild(ta); ta.select();
    let ok = false;
    try { ok = document.execCommand('copy'); } catch (e) { ok = false; }
    ta.remove();
    return ok;
  }

  // QR + address block shown inside the dialog; clicks here don't advance the dialog.
  function payPanel(t, status) {
    const box = document.createElement('div');
    box.className = 'arena-pay';
    box.addEventListener('click', e => e.stopPropagation());
    const img = document.createElement('img');
    img.src = PAY_QR; img.alt = t.payAlt; img.width = 180; img.height = 180;
    const info = document.createElement('div');
    info.className = 'arena-pay-info';
    const addr = document.createElement('code');
    addr.className = 'arena-pay-addr'; addr.textContent = PAY_ADDRESS;
    const note = document.createElement('p');
    note.className = 'arena-pay-note'; note.textContent = t.payNote;
    info.append(addr, note);
    if (status) {
      const st = document.createElement('p');
      st.className = 'arena-pay-status'; st.setAttribute('role', 'status'); st.textContent = status;
      info.append(st);
    }
    box.append(img, info);
    return box;
  }

  // Lobby notice board contents
  function boardPanel(t, keepPage) {
    const box = document.createElement('div');
    box.className = 'arena-board';
    const h = document.createElement('h2');
    h.textContent = t.boardTitle;
    const paper = document.createElement('div');
    paper.className = 'arena-board-paper';
    t.boardBody.forEach(line => { const p = document.createElement('p'); p.textContent = line; paper.appendChild(p); });
    box.append(h, paper, betsPanel(t, keepPage));
    return box;
  }

  // ---------- recent matches on the notice board (bets.js reads them from Arbitrum) ----------
  const BETS_PAGE = 10;
  const BETS_REFRESH_MS = 10000;   // re-read the chain while the board is open
  const shortAddr = a => a.slice(0, 6) + '…' + a.slice(-4);
  const fmtFee = raw => (raw / 1e6).toFixed(2).replace(/\.?0+$/, '') + 'U';
  const bets = { page: 0, sel: -1, list: null, err: false, el: null, timer: null, keys: null };
  let arenaScene = null;   // set in Arena.create; the board starts replays through it

  function betsPanel(t, keepPage) {
    const box = document.createElement('div');
    box.className = 'arena-bets';
    box.addEventListener('click', e => e.stopPropagation());   // paging must not close the board
    bets.el = box; bets.sel = -1;
    if (!keepPage) bets.page = 0;
    renderBets(t);
    refreshBets();
    clearInterval(bets.timer);
    bets.timer = setInterval(() => {
      if (!box.isConnected) { stopBets(); return; }
      refreshBets();
    }, BETS_REFRESH_MS);
    if (!bets.keys) {   // ← / → flip pages, ↑ / ↓ select a match while the board is open
      bets.keys = e => {
        if (!bets.el || !bets.el.isConnected) return;
        if (e.key === 'ArrowLeft' || e.key === 'a' || e.key === 'A') { flipBets(-1); e.preventDefault(); }
        else if (e.key === 'ArrowRight' || e.key === 'd' || e.key === 'D') { flipBets(1); e.preventDefault(); }
        else if (e.key === 'ArrowUp' || e.key === 'w' || e.key === 'W') { moveBetSel(-1); e.preventDefault(); }
        else if (e.key === 'ArrowDown' || e.key === 's' || e.key === 'S') { moveBetSel(1); e.preventDefault(); }
      };
      document.addEventListener('keydown', bets.keys);
    }
    return box;
  }

  const pageBets = () => (bets.list || []).slice(bets.page * BETS_PAGE, (bets.page + 1) * BETS_PAGE);

  function moveBetSel(d) {
    const n = pageBets().length;
    if (!n) return;
    bets.sel = bets.sel < 0 ? (d > 0 ? 0 : n - 1) : (bets.sel + d + n) % n;
    renderBets(TEXT[lang()]);
    const row = bets.el && bets.el.querySelector('tr.is-sel');
    if (row && row.scrollIntoView) row.scrollIntoView({ block: 'nearest' });
  }

  // Replay of a settled match (rule: bets.js matchBattle + assets/match-index.json)
  const MATCH_IDX_V = '20261101s';   // bump with every re-recording (battle-gen/build_match_index.mjs)
  let matchIdxP = null;
  const loadMatchIdx = () => matchIdxP || (matchIdxP = fetch('assets/match-index.json?v=' + MATCH_IDX_V)
    .then(r => { if (!r.ok) throw new Error('index ' + r.status); return r.json(); })
    .catch(e => { matchIdxP = null; throw e; }));

  async function watchBet(e) {
    if (!arenaScene || bets.starting) return;
    bets.starting = true;
    try {
      const idx = await loadMatchIdx();
      const m = window.ArenaBets.matchBattle(e, idx);
      if (!m) return;
      const resume = bets.page;
      stopBets();
      dialog.close();
      arenaScene.startReplay(m, idx.v, shortAddr(e.who), e.tier, resume, e.result.kind === 'win' ? e.result.mult : 0);
    } catch (err) {
      const t = TEXT[lang()];
      const box = bets.el;
      if (box) { const p = box.querySelector('.arena-bets-msg.is-err') || document.createElement('p'); p.className = 'arena-bets-msg is-err'; p.setAttribute('role', 'alert'); p.textContent = t.betsReplayFail; box.appendChild(p); }
    } finally { bets.starting = false; }
  }

  // Space / Enter / A on the open board: play the selected match; with nothing selected, close the board.
  // Installed by openBoard after dialog.notice() (notice clears any previous hook).
  function boardHook() {
    const e = pageBets()[bets.sel];
    if (!e) return false;
    if (e.result.kind !== 'pending') watchBet(e);
    return true;
  }

  function stopBets() { clearInterval(bets.timer); bets.timer = null; bets.el = null; }

  function flipBets(d) {
    if (!bets.list || !bets.list.length) return;
    const pages = Math.ceil(bets.list.length / BETS_PAGE);
    const p = Math.min(pages - 1, Math.max(0, bets.page + d));
    if (p !== bets.page) { bets.page = p; bets.sel = -1; renderBets(TEXT[lang()]); }
  }

  async function refreshBets() {
    if (!window.ArenaBets) { bets.err = true; renderBets(TEXT[lang()]); return; }
    try {
      const [res, R] = await Promise.all([window.ArenaBets.load(), loadRoster()]);
      bets.list = res.list; bets.roster = R; bets.err = false;
    } catch (e) {
      if (!bets.list) bets.err = true;   // keep showing the last good list on a failed refresh
    }
    if (bets.el && bets.el.isConnected) renderBets(TEXT[lang()]);
  }

  function renderBets(t) {
    const box = bets.el;
    if (!box) return;
    const L = lang();
    box.textContent = '';
    const h = document.createElement('h3');
    h.textContent = t.betsTitle;
    box.appendChild(h);
    const msg = s => { const p = document.createElement('p'); p.className = 'arena-bets-msg'; p.setAttribute('role', 'status'); p.textContent = s; box.appendChild(p); };
    if (bets.err) return msg(t.betsError);
    if (!bets.list) return msg(t.betsLoading);
    if (!bets.list.length) return msg(t.betsEmpty);

    const pages = Math.ceil(bets.list.length / BETS_PAGE);
    bets.page = Math.min(bets.page, pages - 1);
    const table = document.createElement('table');
    const cap = document.createElement('caption');
    cap.className = 'arena-sr'; cap.textContent = t.betsCaption;
    const head = document.createElement('tr');
    t.betsCols.forEach(c => { const th = document.createElement('th'); th.scope = 'col'; th.textContent = c; head.appendChild(th); });
    const thead = document.createElement('thead'); thead.appendChild(head);
    const tbody = document.createElement('tbody');
    pageBets().forEach((e, rowI) => {
      const tr = document.createElement('tr');
      const name = bets.roster && bets.roster.tiers[e.tier] ? bets.roster.tiers[e.tier][L] : '';
      const r = e.result;
      const res = r.kind === 'win' ? t.betsWin(r.mult) : r.kind === 'loss' ? t.betsLoss : t.betsPending;
      const cells = [shortAddr(e.who), fmtFee(e.raw), t.betsTier(e.tier, name), res];
      cells.forEach((v, i) => {
        const td = document.createElement('td'); td.textContent = v;
        if (i === 0) { td.className = 'arena-bets-addr'; td.title = e.who; }
        if (i === 3) td.className = 'is-' + r.kind;
        tr.appendChild(td);
      });
      if (rowI === bets.sel) tr.classList.add('is-sel');
      if (r.kind !== 'pending') {   // settled: the whole row opens the replay (mouse, touch, Tab + Enter)
        tr.classList.add('is-watch');
        tr.tabIndex = 0;
        tr.setAttribute('aria-label', t.betsWatch(shortAddr(e.who), fmtFee(e.raw), res));
        tr.addEventListener('click', ev => { ev.stopPropagation(); watchBet(e); });
        tr.addEventListener('keydown', ev => {
          if (ev.key !== 'Enter' && ev.key !== ' ') return;
          ev.preventDefault(); ev.stopPropagation();   // keep the game's Space handler from closing the board
          watchBet(e);
        });
      }
      tbody.appendChild(tr);
    });
    table.append(cap, thead, tbody);
    box.appendChild(table);

    {   // pager is always shown (buttons greyed out when there is only one page)
      const nav = document.createElement('div');
      nav.className = 'arena-bets-nav';
      const btn = (label, d, off) => {
        const b = document.createElement('button');
        b.type = 'button'; b.textContent = label; b.disabled = off;
        b.addEventListener('click', ev => { ev.stopPropagation(); flipBets(d); });
        return b;
      };
      const info = document.createElement('span');
      info.setAttribute('aria-live', 'polite'); info.textContent = t.betsPage(bets.page + 1, pages);
      nav.append(btn(t.betsPrev, -1, bets.page === 0), info, btn(t.betsNext, 1, bets.page >= pages - 1));
      box.appendChild(nav);
    }
  }

  // Tier list for the division menu; fetched once, null if missing.
  let rosterP = null;
  const loadRoster = () => rosterP || (rosterP = fetch('assets/roster.json?v=20261101s')
    .then(r => (r.ok ? r.json() : null)).catch(() => null));

  const playMusic = n => { if (window.ArenaMusic) window.ArenaMusic.play(n); };

  let hintMode = 'arena';
  function setHint(mode) {
    hintMode = mode;
    const t = TEXT[lang()];
    const touch = matchMedia('(pointer: coarse)').matches;
    document.getElementById('hint').textContent =
      mode === 'menu' ? t.hintMenu : mode === 'battle' ? t.hintBattle : touch ? t.hintTouch : t.hint;
  }

  // ---------- virtual pad (touch) ----------
  const pad = { held: null, action: false };
  function bindPad() {
    document.querySelectorAll('#pad [data-dir]').forEach(btn => {
      const dir = btn.dataset.dir;
      const down = e => { e.preventDefault(); pad.held = dir; };
      const up = e => { e.preventDefault(); if (pad.held === dir) pad.held = null; };
      btn.addEventListener('pointerdown', down);
      btn.addEventListener('pointerup', up);
      btn.addEventListener('pointerleave', up);
      btn.addEventListener('pointercancel', up);
    });
    const a = document.getElementById('pad-a');
    a.addEventListener('pointerdown', e => { e.preventDefault(); pad.action = true; });
  }

  class Arena extends Phaser.Scene {
    constructor() { super('arena'); }

    preload() {
      this.load.image('tiles', 'assets/tileset.png');
      this.load.tilemapTiledJSON('map', 'assets/arena.json?v=20261101g');
      this.load.atlas('player', 'assets/player.png', 'assets/player.json');
      this.load.image('board', 'assets/board.png?v=20261101d');
    }

    create() {
      const map = this.make.tilemap({ key: 'map' });
      const ts = map.addTilesetImage('tileset', 'tiles', 32, 32, 1, 2);
      ['Ground1', 'Ground2', 'Collision1', 'Collision2'].forEach(n => map.createLayer(n, ts, 0, 0));
      map.createLayer('Above', ts, 0, 0).setDepth(10);

      const prop = k => (map.properties.find(p => p.name === k) || {}).value;
      this.solid = JSON.parse(prop('solid'));
      const [sx, sy] = prop('spawn').split(',').map(Number);
      // receptionists: main hall + east hall (same dialogue for now)
      this.npcs = ['npc', 'npc2'].map(prop).filter(Boolean).map(v => { const [x, y] = v.split(',').map(Number); return { x, y }; });
      this.mapW = map.width; this.mapH = map.height;

      // Notice board (w x h tiles); walk up to it and press A, or click/tap it
      const bp = prop('board');
      if (bp) {
        const [bx, by, bw = 2, bh = 2] = bp.split(',').map(Number);
        this.board = { x: bx, y: by, w: bw, h: bh };
        this.add.image(bx * TILE, by * TILE, 'board').setOrigin(0, 0).setDepth(4)
          .setInteractive({ useHandCursor: true })
          .on('pointerdown', (p, lx, ly, ev) => {
            if (dialog.open) return;
            ev.stopPropagation();   // keep the scene-level tap handler from closing it at once
            this.openBoard();
          });
      }

      // Player: 32x41 sprite, feet on the bottom of its tile
      this.tx = sx; this.ty = sy; this.facing = 'up'; this.moving = false;
      this.player = this.add.sprite(0, 0, 'player', 'ariel-back').setOrigin(0.5, 1).setDepth(5);
      this.placePlayer();
      for (const k of ['left', 'right', 'front', 'back']) {
        this.anims.create({
          key: k,
          frames: this.anims.generateFrameNames('player', { prefix: `ariel-${k}-walk.`, start: 0, end: 3, zeroPad: 3 }),
          frameRate: 10, repeat: -1,
        });
      }

      const cam = this.cameras.main;
      cam.startFollow(this.player, true);
      cam.setRoundPixels(true);
      this.fitCamera();
      this.scale.on('resize', () => this.fitCamera());

      this.keys = this.input.keyboard.addKeys('UP,DOWN,LEFT,RIGHT,W,A,S,D,SPACE,ENTER,Z');
      const talk = () => this.interact();
      this.keys.SPACE.on('down', talk);
      this.keys.ENTER.on('down', talk);
      this.keys.Z.on('down', talk);
      this.input.on('pointerdown', () => { if (dialog.open) dialog.advance(); });

      setHint('arena');
      playMusic('lobby');
      window.onArenaLang = () => { setHint(hintMode); if (window.ArenaMusic) window.ArenaMusic.refreshLabel(); };
      this.events.on('wake', this.onWake, this);
      arenaScene = this;
    }

    fitCamera() {
      // Integer zoom so pixels stay square; show the whole room when there's room for it.
      const { width, height } = this.scale.gameSize;
      const mw = this.mapW * TILE, mh = this.mapH * TILE;
      const fit = Math.min(width / mw, height / mh);
      // Half-step zoom keeps pixels even on desktop; small screens shrink to fit the whole room.
      const zoom = fit >= 1 ? Math.floor(fit * 2) / 2 : Math.max(0.5, fit);
      const cam = this.cameras.main;
      cam.setZoom(zoom);
      // When the room is smaller than the view, widen the bounds symmetrically so it sits centered.
      const vw = width / zoom, vh = height / zoom;
      const bw = Math.max(mw, vw), bh = Math.max(mh, vh);
      cam.setBounds((mw - bw) / 2, (mh - bh) / 2, bw, bh);
    }

    placePlayer() {
      this.player.setPosition(this.tx * TILE + TILE / 2, (this.ty + 1) * TILE);
    }

    blocked(x, y) {
      return x < 0 || y < 0 || x >= this.mapW || y >= this.mapH || this.solid[y][x] === 1;
    }

    face(dir) {
      this.facing = dir;
      this.player.anims.stop();
      this.player.setFrame(`ariel-${DIRS[dir].anim}`);
    }

    interact() {
      if (dialog.open) { dialog.advance(); return; }
      if (this.moving) return;
      const d = DIRS[this.facing];
      const fx = this.tx + d.dx, fy = this.ty + d.dy;
      // NPCs stand behind a counter: talk across it (facing up at the counter tile in front of them)
      const b = this.board;
      if (b && fx >= b.x && fx < b.x + b.w && fy >= b.y && fy < b.y + b.h) { this.openBoard(); return; }
      const i = this.npcs.findIndex(n => (this.facing === 'up' && fx === n.x && fy === n.y + 2) || (fx === n.x && fy === n.y));
      if (i === 0) this.talkToFeeNpc();   // main hall: entry fee
      else if (i > 0) this.talkToNpc();   // east hall: pick a champion and watch
    }

    openBoard(keepPage) {
      if (window.ArenaMusic) window.ArenaMusic.sfx('select');
      dialog.notice(boardPanel(TEXT[lang()], keepPage));
      dialog.noticeHook = boardHook;
    }

    // Notice-board replay: battle n of champion m.champ, challenger shown as the entrant's address.
    startReplay(m, v, who, tier, page, crit) {
      this.replayPage = page;
      this.face('up');
      this.cameras.main.fadeOut(250, 255, 255, 255);
      this.cameras.main.once('camerafadeoutcomplete', () => {
        this.scene.sleep();
        this.scene.run('battle', { champ: m.champ, n: m.n, chunk: m.chunk, expect: m.expect, who, crit, v, music: tier >= 9 ? 'legend' : 'battle', replay: true });
      });
    }

    talkToNpc() {
      const t = TEXT[lang()];
      dialog.start(t.npc, () => this.askPick());
    }

    // Main-hall receptionist: pick a tier, then show the entry-fee QR (tier n = n USDC).
    talkToFeeNpc() {
      const t = TEXT[lang()];
      dialog.start(t.feeNpc, () => this.askFeeTier());
    }

    askFeeTier(sel = 0) {
      const L = lang(), t = TEXT[L];
      setHint('menu');
      loadRoster().then(R => {
        if (!R) { setHint('arena'); dialog.start(t.bye); return; }
        const opts = [...R.open].sort((a, b) => a - b)
          .map(n => ({ value: n, label: t.feeTier(n, R.tiers[n][L], tierFee(n)) }));
        opts.push({ value: null, label: t.cancel });
        dialog.choose(t.feeAsk, opts, tier => {
          if (!tier) { setHint('arena'); dialog.start(t.bye); return; }
          this.showPay(R, tier, opts.findIndex(o => o.value === tier));
        }, sel);
      });
    }

    showPay(R, tier, tierSel, status = '', sel = 0) {
      const L = lang(), t = TEXT[L];
      const opts = [
        { value: '__copy', label: t.copy },
        { value: '__back', label: t.back },
        { value: '__close', label: t.close },
      ];
      dialog.choose(t.payText(tier, R.tiers[tier][L], tierFee(tier)), opts, async pick => {
        if (pick === '__copy') {
          const ok = await copyText(PAY_ADDRESS);
          this.showPay(R, tier, tierSel, ok ? t.copied : t.copyFail, 0);
        } else if (pick === '__back') this.askFeeTier(tierSel);
        else { setHint('arena'); dialog.start(t.bye); }
      }, sel, payPanel(t, status));
    }

    // Step 1: division (tier 1-10). The tier list comes from assets/roster.json, made by
    // battle-gen/build_tier_battles.mjs; each Pokémon's battles are in assets/battles/<id>.json.
    askPick(sel = 0) {
      const L = lang(), t = TEXT[L];
      setHint('menu');
      loadRoster().then(R => {
        if (!R) { setHint('arena'); dialog.start(t.bye); return; }
        const opts = [...R.open].sort((a, b) => a - b)
          .map(n => ({ value: n, label: t.tier(n, R.tiers[n][L], R.tiers[n].mon.length) }));
        opts.push({ value: null, label: t.cancel });
        dialog.choose(t.askTier, opts, tier => {
          if (!tier) { setHint('arena'); dialog.start(t.bye); return; }
          this.askMon(R, tier, 0, opts.findIndex(o => o.value === tier));
        }, sel);
      });
    }

    // Step 2: Pokémon in that tier, PAGE_SIZE per page (tiers 3/5/6/7 have 60-70).
    // keep = '__prev' / '__next' puts the cursor back on that button, so repeated presses flip pages.
    askMon(R, tier, page, tierSel, keep) {
      const L = lang(), t = TEXT[L];
      const all = R.tiers[tier].mon;
      const pages = Math.max(1, Math.ceil(all.length / PAGE_SIZE));
      const opts = all.slice(page * PAGE_SIZE, (page + 1) * PAGE_SIZE).map(k => ({ value: k, label: R.mon[k][L] }));
      if (pages > 1) {
        opts.push({ value: '__prev', label: t.prevPage });
        opts.push({ value: '__next', label: t.nextPage });
      }
      opts.push({ value: '__back', label: t.back });
      const prompt = pages > 1 ? t.askPage(page + 1, pages) : t.ask;
      const sel = keep ? opts.findIndex(o => o.value === keep) : 0;
      dialog.choose(prompt, opts, pick => {
        if (pick === '__back') { this.askPick(tierSel); return; }
        if (pick === '__prev' || pick === '__next') {
          this.askMon(R, tier, (page + (pick === '__next' ? 1 : -1) + pages) % pages, tierSel, pick);
          return;
        }
        setHint('arena');
        dialog.start(t.go(R.mon[pick][L]), () => this.startBattle(pick, R.v, tier >= 9 ? 'legend' : 'battle', R.mon[pick].battles, R.chunk));   // pick = champion
      }, sel);
    }

    startBattle(pick, v, music, count, chunk) {
      this.face('up');
      this.cameras.main.fadeOut(250, 255, 255, 255);
      this.cameras.main.once('camerafadeoutcomplete', () => {
        this.scene.sleep();
        this.scene.run('battle', { champ: pick, v, music, count, chunk });
      });
    }

    onWake(sys, data) {
      this.cameras.main.fadeIn(250, 255, 255, 255);
      this.fitCamera();
      playMusic('lobby');
      const t = TEXT[lang()];
      if (data && data.replay) { bets.page = this.replayPage || 0; this.openBoard(true); return; }   // back to the board
      if (data && data.result) dialog.start(t[data.result === 'win' ? 'win' : 'lose']);
    }

    heldDir() {
      const k = this.keys;
      if (k.LEFT.isDown || k.A.isDown) return 'left';
      if (k.RIGHT.isDown || k.D.isDown) return 'right';
      if (k.UP.isDown || k.W.isDown) return 'up';
      if (k.DOWN.isDown || k.S.isDown) return 'down';
      return pad.held;
    }

    update() {
      if (pad.action) { pad.action = false; this.interact(); }
      if ((dialog.choice || (bets.el && bets.el.isConnected)) && pad.held && !this.padRepeat) {   // touch d-pad drives the menu / board
        this.padRepeat = true;
        const d = pad.held === 'up' ? -1 : pad.held === 'down' ? 1 : 0;
        if (dialog.choice) { if (d) dialog.move(d); }
        else if (d) moveBetSel(d);
        else flipBets(pad.held === 'left' ? -1 : 1);
      }
      if (!pad.held) this.padRepeat = false;
      if (this.moving || dialog.open) return;
      const dir = this.heldDir();
      if (!dir) {
        if (this.player.anims.isPlaying) this.face(this.facing);
        return;
      }
      const d = DIRS[dir];
      this.facing = dir;
      const nx = this.tx + d.dx, ny = this.ty + d.dy;
      if (this.blocked(nx, ny)) { this.face(dir); return; }
      this.moving = true;
      this.player.anims.play(d.anim, true);
      this.tx = nx; this.ty = ny;
      this.tweens.add({
        targets: this.player,
        x: nx * TILE + TILE / 2,
        y: (ny + 1) * TILE,
        duration: STEP_MS,
        onComplete: () => { this.moving = false; },
      });
    }
  }

  window.ArenaUI = { dialog, pad, setHint };

  function boot() {
    dialog.init();
    bindPad();
    const host = document.getElementById('game');
    new Phaser.Game({
      type: Phaser.AUTO,
      parent: host,
      pixelArt: true,
      backgroundColor: '#04241f',
      scale: { mode: Phaser.Scale.RESIZE, width: host.clientWidth, height: host.clientHeight },
      scene: [Arena, window.ArenaBattle],
    });
  }
  window.addEventListener('DOMContentLoaded', boot);
})();
